"""
cli_argument_validation.py

Parses a list of CLI argument strings and returns a validated options dict.
"""

from __future__ import annotations

VALID_FORMATS = ("json", "csv")
DEFAULT_LIMIT = 100
DEFAULT_FORMAT = "json"

# Flags that consume the next token as their value.
VALUE_FLAGS = {"--input", "--limit", "--format", "--tag"}
# Flags that are boolean switches.
BOOL_FLAGS = {"--dry-run"}
ALL_FLAGS = VALUE_FLAGS | BOOL_FLAGS


def _check_flag_known(token: str) -> None:
    """Raise ValueError if token is not a recognised flag."""
    if token not in ALL_FLAGS:
        raise ValueError(f"Unknown flag: {token!r}")


def _check_value_provided(flag: str, i: int, argv: list[str]) -> None:
    """Raise ValueError if the next token is absent or looks like a flag."""
    if i + 1 >= len(argv) or argv[i + 1].startswith("--"):
        raise ValueError(f"Flag {flag!r} requires a value but none was provided")


def _process_bool_flag(token: str, raw: dict, i: int) -> int:
    """Record a boolean flag and return the next index."""
    if token in raw:
        raise ValueError(f"Duplicate flag: {token!r}")
    raw[token] = True
    return i + 1


def _process_value_flag(
    token: str,
    raw: dict,
    tag_values: list[str],
    argv: list[str],
    i: int,
) -> int:
    """Record a value flag (or accumulate --tag) and return the next index."""
    _check_value_provided(token, i, argv)
    value = argv[i + 1]
    if token == "--tag":
        tag_values.append(value)
    else:
        if token in raw:
            raise ValueError(f"Duplicate flag: {token!r}")
        raw[token] = value
    return i + 2


def _parse_tokens(argv: list[str]) -> tuple[dict[str, str | bool], list[str]]:
    """
    Walk argv left-to-right, collecting raw flag values.

    Returns a tuple of:
      - dict mapping flag name -> raw string value (or True for bool flags)
      - list of raw strings for --tag occurrences (may repeat)

    Raises ValueError for unknown flags, repeated flags, or missing values.
    """
    if not isinstance(argv, list):
        raise ValueError(f"argv must be a list, got {type(argv).__name__!r}")
    for idx, item in enumerate(argv):
        if not isinstance(item, str):
            raise ValueError(
                f"argv[{idx}] must be a str, got {type(item).__name__!r}"
            )

    raw: dict[str, str | bool] = {}
    tag_values: list[str] = []
    i = 0
    while i < len(argv):
        token = argv[i]
        if not token.startswith("--"):
            raise ValueError(f"Unexpected positional argument: {token!r}")
        _check_flag_known(token)
        if token in BOOL_FLAGS:
            i = _process_bool_flag(token, raw, i)
        else:
            i = _process_value_flag(token, raw, tag_values, argv, i)
    return raw, tag_values


def _require(raw: dict, flag: str) -> str:
    if not isinstance(raw, dict):
        raise ValueError(f"raw must be a dict, got {type(raw).__name__!r}")
    if not isinstance(flag, str):
        raise ValueError(f"flag must be a str, got {type(flag).__name__!r}")
    if flag not in raw:
        raise ValueError(f"Required flag {flag!r} is missing")
    return raw[flag]  # type: ignore[return-value]


def _parse_limit(value: str) -> int:
    if not isinstance(value, str):
        raise ValueError(
            f"_parse_limit expects a str, got {type(value).__name__!r}"
        )
    try:
        n = int(value)
    except ValueError:
        raise ValueError(f"--limit must be an integer, got {value!r}")
    if n <= 0:
        raise ValueError(f"--limit must be a positive integer, got {n}")
    return n


def _parse_format(value: str) -> str:
    if not isinstance(value, str):
        raise ValueError(
            f"_parse_format expects a str, got {type(value).__name__!r}"
        )
    if value not in VALID_FORMATS:
        raise ValueError(
            f"--format must be one of {VALID_FORMATS}, got {value!r}"
        )
    return value


def _parse_tag_entry(entry: str) -> tuple[str, str]:
    """Parse a single KEY=VALUE string; raise ValueError on bad format."""
    if not isinstance(entry, str):
        raise ValueError(
            f"_parse_tag_entry expects a str, got {type(entry).__name__!r}"
        )
    if "=" not in entry:
        raise ValueError(
            f"--tag value must be in KEY=VALUE format, got {entry!r}"
        )
    key, _, value = entry.partition("=")
    if not key:
        raise ValueError(f"--tag key must not be empty, got {entry!r}")
    return key, value


def _parse_tags(tag_values: list[str]) -> dict[str, str]:
    """
    Parse a list of KEY=VALUE strings into a dict.
    Duplicate keys use the last value.
    Raises ValueError if any entry is not in KEY=VALUE form.
    """
    if not isinstance(tag_values, list):
        raise ValueError(
            f"tag_values must be a list, got {type(tag_values).__name__!r}"
        )
    tags: dict[str, str] = {}
    for entry in tag_values:
        key, value = _parse_tag_entry(entry)
        tags[key] = value
    return tags


def parse_cli_args(argv: list[str]) -> dict:
    """
    Parse a list of CLI argument strings into a validated options dict.

    Parameters
    ----------
    argv:
        Raw argument tokens, e.g. ["--input", "file.txt", "--dry-run"].
        Must be a list of str.

    Returns
    -------
    dict with keys: input (str), limit (int), format (str), dry_run (bool),
    tags (dict[str, str]).

    Raises
    ------
    ValueError
        For missing required flags, unknown flags, missing values, invalid
        values, or incorrect argument types.
    """
    if argv is None:
        raise ValueError("argv must not be None")
    if not isinstance(argv, list):
        raise ValueError(
            f"argv must be a list of str, got {type(argv).__name__!r}"
        )

    raw, tag_values = _parse_tokens(argv)

    input_path = _require(raw, "--input")

    limit_raw = raw.get("--limit")
    limit = _parse_limit(limit_raw) if limit_raw is not None else DEFAULT_LIMIT  # type: ignore[arg-type]

    format_raw = raw.get("--format")
    fmt = _parse_format(format_raw) if format_raw is not None else DEFAULT_FORMAT  # type: ignore[arg-type]

    dry_run = bool(raw.get("--dry-run", False))

    tags = _parse_tags(tag_values)

    return {
        "input": input_path,
        "limit": limit,
        "format": fmt,
        "dry_run": dry_run,
        "tags": tags,
    }

